/* v1.0.9 hours display */
window.fmtHoursHM = window.fmtHoursHM || function fmtHoursHM(h){h=Number(h)||0;var neg=h<0?'-':'';var tm=Math.round(Math.abs(h)*60);var hh=Math.floor(tm/60),mm=tm-hh*60;if(hh===0&&mm===0)return '0 ч.';if(mm===0)return neg+hh+' ч.';if(hh===0)return neg+mm+' мин.';return neg+hh+' ч. '+mm+' мин.';};
/* PATCH 1.0.1 — guard-флаги для старых перехватчиков (PATCH 1.0.1-fix: __trkLogSaveUnifiedV1035 отключает старый блок B3, новый блок ниже использует __trkLogSaveUnifiedV1101) */
(function(){
    'use strict';
    window.__trkOverflowModalV2 = true;
    window.__trkLogFormFocusFetch = true;
    window.__trkAutoAssignFetch = true;
    window.__trkLogDupDayFetch = true;
    window.__trkCloseAllAfterLogV1024 = true;
    window.__trkMultiFieldsFixV1032 = true;
    window.__trkCompactModeV112 = true;
    window.__trkLogSaveUnifiedV1035 = true;
})();
/* ============================================================
   PATCH 1.0.3 — реестр плагинов + дропдаун под вкладкой «Статистика»
   ============================================================ */
(function(){
'use strict';
if (window.__trkPluginMenuV103) return;
window.__trkPluginMenuV103 = true;

window.__trkPluginRegistry = window.__trkPluginRegistry || [];

window.__trkRegisterPlugin = function(opts){
    if (!opts) return;
    if (!opts.url && typeof opts.onClick !== 'function') return;
    var arr = window.__trkPluginRegistry;
    var key = opts.id || opts.url || opts.name || '';
    if (!key) return;
    for (var i = 0; i < arr.length; i++) {
        var ex = arr[i];
        if ((opts.id && ex.id === opts.id) || (opts.url && ex.url && ex.url === opts.url)) return;
    }
    arr.push(opts);
    if (window.__trkBuildStatsMenu) setTimeout(window.__trkBuildStatsMenu, 30);
};

window.__trkBuildStatsMenu = function(){
    var statsTab = document.querySelector('.tracker-tab[data-tab="stats"]');
    if (!statsTab) return;
    if (!statsTab.querySelector('.tab-menu-arrow')) {
        var arrow = document.createElement('span');
        arrow.className = 'tab-menu-arrow';
        arrow.textContent = '▾';
        statsTab.appendChild(arrow);
    }
    var menu = document.getElementById('statsPluginMenu');
    if (!menu) {
        menu = document.createElement('div');
        menu.id = 'statsPluginMenu';
        menu.className = 'stats-plugin-menu';
        document.body.appendChild(menu);
    }
    var perms = window.REESTR_PERMS || {};
    var html = '<div class="spm-item" data-action="builtin"><span>📊</span><span>Встроенная статистика</span></div>';
    var arr = window.__trkPluginRegistry || [];
    var _seenUrls = {};
    for (var i = 0; i < arr.length; i++) {
        var p = arr[i];
        if (p.url) _seenUrls[p.url] = true;   // PATCH v1.0.14-fix: плагин сам зарегистрировал пункт — хардкод-ссылку ниже не дублируем
        if (p.perm && !perms[p.perm]) continue;
        if (typeof p.onClick === 'function') {
            html += '<button type="button" class="spm-item" data-plugin-idx="' + i + '"><span>' + (p.icon || '🔗') + '</span><span>' + p.name + '</span></button>';
        } else if (p.url && p.url !== '#') {
            html += '<a class="spm-item" href="' + p.url + '"><span>' + (p.icon || '🔗') + '</span><span>' + p.name + '</span></a>';
        } else {
            html += '<button type="button" class="spm-item" data-plugin-idx="' + i + '"><span>' + (p.icon || '🔗') + '</span><span>' + p.name + '</span></button>';
        }
    }
    if (perms['tab.stats'] && !_seenUrls['/plugins/task_heatmap/']) {
        html += '<a class="spm-item" href="/plugins/task_heatmap/"><span>🔥</span><span>Тепловая карта задач</span></a>';
    }

    if (perms['tab.settings'] && !_seenUrls['/plugins/weekly_report/']) {
        html += '<a class="spm-item" href="/plugins/weekly_report/"><span>📥</span><span>Недельные отчёты</span></a>';
    }
    menu.innerHTML = html;
};

document.addEventListener('click', function(e){
    if (!e.target || !e.target.closest) return;
    // PATCH 1.0.12: клик по всей кнопке «Статистика» открывает меню,
    // вкладка при этом не переключается.
    var statsTab = e.target.closest('.tracker-tab[data-tab="stats"]');
    if (statsTab) {
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        var menu = document.getElementById('statsPluginMenu');
        if (!menu) { window.__trkBuildStatsMenu(); menu = document.getElementById('statsPluginMenu'); }
        if (!menu) return;
        var rect = statsTab.getBoundingClientRect();
        menu.style.left = Math.min(rect.left, window.innerWidth - 280) + 'px';
        menu.style.top = (rect.bottom + 6) + 'px';
        menu.classList.toggle('active');
        return;
    }
    var builtin = e.target.closest('#statsPluginMenu [data-action="builtin"]');
    if (builtin) {
        e.preventDefault();
        e.stopPropagation();
        var st = document.querySelector('.tracker-tab[data-tab="stats"]');
        if (st) {
            document.querySelectorAll('.tracker-tab').forEach(function(t) {
                t.classList.toggle('active', t === st);
            });
            document.querySelectorAll('.tracker-panel').forEach(function(p) {
                p.classList.toggle('active', p.id === 'panel-stats');
            });
            try { localStorage.setItem('tracker_activeTab', 'stats'); } catch (er) {}
            if (typeof window.__trkLoadStats === 'function') {
                try { window.__trkLoadStats(); } catch (er) {}
            }
        }
        var m = document.getElementById('statsPluginMenu');
        if (m) m.classList.remove('active');
        return;
    }
    if (!e.target.closest('#statsPluginMenu')) {
        var m2 = document.getElementById('statsPluginMenu');
        if (m2 && m2.classList.contains('active')) m2.classList.remove('active');
    }
}, true);

setTimeout(function(){ try { window.__trkBuildStatsMenu(); } catch(e){} }, 500);
setTimeout(function(){ try { window.__trkBuildStatsMenu(); } catch(e){} }, 1500);
setTimeout(function(){ try { window.__trkBuildStatsMenu(); } catch(e){} }, 3000);

// PATCH 1.0.16: клик по кнопке плагина с onClick
document.addEventListener('click', function(e){
    if (!e.target || !e.target.closest) return;
    var btn = e.target.closest('#statsPluginMenu [data-plugin-idx]');
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    var idx = parseInt(btn.getAttribute('data-plugin-idx'), 10);
    var arr = window.__trkPluginRegistry || [];
    if (!isNaN(idx) && arr[idx] && typeof arr[idx].onClick === 'function') {
        try { arr[idx].onClick(); } catch (er) { console.error('[plugin-menu]', er); }
    }
    var m = document.getElementById('statsPluginMenu');
    if (m) m.classList.remove('active');
}, true);

})();
/* ============================================================
   PATCH 1.0.1 — применён (2026-10-15)
   Guard-флаги конфликтов + маркер версии.
   Проверка в браузере: window.__trkPatchVersion
   ============================================================ */
(function () {
    'use strict';
    window.__trkPatchVersion = '1.0.1';
    window.__trkPatchAppliedAt = '2026-10-15';
    window.__trkLogEditTaskMergeV1015 = true;
    window.__trkDelLogFeedbackV1013 = true;
    window.__trkQuickAddAssigned = true;
    try {
        console.log('%c[tracker.js] патч 1.0.1 применён', 'color:#2ecc71;font-weight:bold');
    } catch (e) {}
})();

/* ============================================================
   PATCH 1.0.1 — Фикс конфликтов патчей (guard-флаги)
   -------------------------------------------------------------
   ВАЖНО: prepend. Флаги выставляются ДО исполнения старых IIFE,
   иначе те успевают зарегистрировать свои обработчики.
   ============================================================ */
(function() {
    'use strict';

    // v1.0.15 — двойное заполнение формы отметки при редактировании.
    // Полностью перекрыт v1.0.16 (MutationObserver на #logModal).
    window.__trkLogEditTaskMergeV1015 = true;

    // v1.0.13 — старый оверлей удаления отметки с визуальными артефактами.
    // Перекрыт v1.0.18 (чистый оверлей на .modal, снимается по promise).
    window.__trkDelLogFeedbackV1013 = true;

    // v1.2.3 — быстрый quick-add, недостижим из-за stopImmediatePropagation
    // в v1.0.3. Guard-флаг экономит регистрацию лишнего fetch-хука.
    window.__trkQuickAddAssigned = true;

})();
/* Трекер задач — клиентская логика (standalone). v1.4 */
(function() {
'use strict';

var PERMS = window.REESTR_PERMS || {};
function hasPerm(k) { return !!PERMS[k]; }

var state = {
    employees: [], tasks: [], log: [], emoji: [], palette: [],
    departments: [], teams: [], holidays: {},
    allTags: [], tagPresets: [],
    statusLabels: {}, taskStatusLabels: {}, absenceTypes: {},
    calendar: null, heatmap: null, summary: null, summaryIsGrid: true,
    currentYM: '', currentEmployee: '', currentDepartment: '', currentTeam: '', currentDay: '',
    calViewMode: 'tasks', tskViewMode: 'all',
    tskDisplayMode: 'list', tskGridCols: 3, tskView: 'tile',
    hmYM: '', hmDateFrom: '', hmDateTo: '',
    sumViewMode: 'grid', sumShowDayTotals: true, sumTaskRowMode: 'full',
    today: '', theme: 'dark', maskNames: false,
    currentUser: null,
    calExpandOnHover: true,
    tskCompactMode: false,
};

var MONTHS_RU = ['Январь','Февраль','Март','Апрель','Май','Июнь',
                 'Июль','Август','Сентябрь','Октябрь','Ноябрь','Декабрь'];

var CSRF = window.REESTR_CSRF || '';
window.__trkState = state;
var meta = document.querySelector('meta[name="csrf-token"]');
if (!CSRF && meta) CSRF = meta.getAttribute('content') || '';

var _tagDraft = [];
// PATCH v1.0.19: экспортируем ссылку на массив, чтобы PATCH 1.0.8::_forceTagDraft
// мог мутировать её (а не заменять reference), и saveTask видел теги.
window.__trkTagDraft = _tagDraft;
var _logExistingMode = 'me';
var _logExistingEmpId = '';

/* ============================================================
   УТИЛИТЫ
   ============================================================ */
function $(id) { return document.getElementById(id); }
function on(id, ev, fn) {
    var el = $(id);
    if (el) el.addEventListener(ev, fn);
    return el;
}
function escapeHtml(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) {
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
}
function maskName(name) {
    if (!state.maskNames) return name;
    var s = String(name == null ? '' : name);
    if (!s) return s;
    return s.split(/\s+/).map(function(w) {
        if (w.length <= 1) return w;
        return w[0] + new Array(w.length).join('*');
    }).join(' ');
}
function escName(name) { return escapeHtml(maskName(name)); }

function notify(msg, kind) {
    var n = $('trackerNotif'); if (!n) return;
    var isErr = (kind === 'error');
    n.className = 'tracker-notification show' + (isErr ? ' error' : '');
    clearTimeout(n._t);
    // PATCH v1.0.11: ошибка не автоскрывается — только по крестику или новому notify
    if (isErr) {
        n.innerHTML = '';
        var msgSpan = document.createElement('span');
        msgSpan.className = 'notif-msg';
        msgSpan.textContent = String(msg == null ? '' : msg);
        n.appendChild(msgSpan);
        var closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'notif-close';
        closeBtn.setAttribute('aria-label', 'Закрыть');
        closeBtn.title = 'Закрыть';
        closeBtn.textContent = '×';
        closeBtn.addEventListener('click', function() {
            n.classList.remove('show');
            clearTimeout(n._t);
        });
        n.appendChild(closeBtn);
    } else {
        n.textContent = msg;
        n._t = setTimeout(function() { n.classList.remove('show'); }, 4500);
    }
}
window.__trackerNotify = notify;

/* ============================================================
   ЛОАДЕР
   ============================================================ */
var _reqCount = 0;
var _minHideTimer = null;
var LOADER_MIN_MS = 250;

function _setLoaderLabel(label) {
    var l = $('globalLoader');
    if (!l) return;
    var t = l.querySelector('.gl-text');
    if (!t) return;
    t.textContent = label || 'Загрузка…';
}
// PATCH v1.0.11: опциональный label — 'Сохранение…', 'Удаление…' и т.п.
// PATCH v1.0.12: стек меток параллельных запросов.
var _loaderStack = [];
function _showLoader(label) {
    _reqCount++;
    _loaderStack.push(label || '');
    if (_minHideTimer) { clearTimeout(_minHideTimer); _minHideTimer = null; }
    var l = $('globalLoader');
    if (l) l.classList.add('active');
    _setLoaderLabel(label);
}
function _hideLoader() {
    _reqCount = Math.max(0, _reqCount - 1);
    _loaderStack.pop();
    if (_reqCount > 0) {
        var top = _loaderStack.length ? _loaderStack[_loaderStack.length - 1] : '';
        _setLoaderLabel(top);
        return;
    }
    if (_minHideTimer) return;
    _minHideTimer = setTimeout(function() {
        if (_reqCount === 0) {
            var l = $('globalLoader');
            if (l) l.classList.remove('active');
            _setLoaderLabel('');
        }
        _minHideTimer = null;
    }, LOADER_MIN_MS);
}
(function() {
    var SEL = [
        'button', 'a[href]',
        '.tracker-tab', '.segmented button', '.dict-action-btn', '.btn',
        '.cal-nav-btn', '.period-arrow-btn', '.log-existing-tab',
        '.tracker-back-btn', '.theme-toggle-btn', '.mask-toggle-btn',
        '.user-btn', '.dict-add-btn', '.icon-picker-btn', '.emoji-btn',
        '.palette-dot', '.assignees-item', '.dept-multi-item',
        '.chart-bar', '.chart-slice', '.donut-legend-item.clickable',
        '.task-tag-chip.clickable',
    ].join(', ');
    document.addEventListener('click', function(e) {
        var t = e.target.closest(SEL);
        if (!t) return;
        if (t.disabled) return;
        if (t.dataset && t.dataset.noLoader === '1') return;
        _showLoader();
        setTimeout(_hideLoader, 0);
    }, true);
})();

function apiJson(url, options) {
    options = options || {};
    options.headers = Object.assign({}, options.headers || {});
    if (CSRF && options.method && options.method !== 'GET')
        options.headers['X-CSRF-Token'] = CSRF;
    if (!options.credentials) options.credentials = 'same-origin';
    if (!options.cache) options.cache = 'no-store';
    // PATCH v1.0.11: пробрасываем подпись загрузчика (options.label)
    _showLoader(options.label);
    return fetch(url, options).then(function(r) {
        if (r.status === 401) { location.href = '/login'; return new Promise(function(){}); }
        if (r.status === 403) {
            return r.text().then(function(t) {
                var m = 'Недостаточно прав';
                try { var j = JSON.parse(t); if (j.error) m += ': ' + j.error; } catch (e) {}
                throw new Error(m);
            });
        }
        if (!r.ok) {
            return r.text().then(function(t) {
                var msg = 'HTTP ' + r.status;
                try { var j = JSON.parse(t); if (j && j.error) msg += ' — ' + j.error; }
                catch (e) { if (t) msg += ' — ' + t.slice(0, 200); }
                throw new Error(msg);
            });
        }
        return r.json();
    }).finally(_hideLoader);
}

/* ============================================================
   ДАТЫ / ЧИСЛА
   ============================================================ */
function todayYM() {
    var t = new Date();
    return t.getFullYear() + '-' + String(t.getMonth() + 1).padStart(2, '0');
}
function todayISO() {
    var t = new Date();
    return t.getFullYear() + '-' + String(t.getMonth() + 1).padStart(2, '0') + '-' + String(t.getDate()).padStart(2, '0');
}
function isoFromDate(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function parseISO(s) {
    var p = String(s).split('-');
    return new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
}
function addDaysISO(iso, delta) {
    var d = parseISO(iso);
    d.setDate(d.getDate() + delta);
    return isoFromDate(d);
}
function firstOfMonthISO(ym) { return ym + '-01'; }
function firstOfMonthISOFromDate(d) {
    var t = d || new Date();
    return t.getFullYear() + '-' + String(t.getMonth() + 1).padStart(2, '0') + '-01';
}
function getMondayISO() {
    var t = new Date();
    var wd = t.getDay();
    var diff = (wd === 0) ? -6 : (1 - wd);
    var mon = new Date(t.getTime() + diff * 86400000);
    return isoFromDate(mon);
}
function getSundayISO() {
    var mon = getMondayISO();
    var sun = new Date(new Date(mon + 'T00:00:00').getTime() + 6 * 86400000);
    return isoFromDate(sun);
}
function setDefaultWeekRange() {
    var a = $('sumDateFrom'), b = $('sumDateTo');
    if (a) a.value = getMondayISO();
    if (b) b.value = getSundayISO();
}
function setMonthRange() {
    var a = $('sumDateFrom'), b = $('sumDateTo');
    if (a) a.value = firstOfMonthISOFromDate(new Date());
    if (b) b.value = todayISO();
}
function formatDateHuman(iso) {
    try {
        var p = iso.split('-');
        return parseInt(p[2], 10) + ' ' + MONTHS_RU[parseInt(p[1], 10) - 1].toLowerCase() + ' ' + p[0];
    } catch (e) { return iso; }
}
function formatDateShort(iso) {
    try { var p = iso.split('-'); return parseInt(p[2], 10) + '.' + p[1]; }
    catch (e) { return iso; }
}
function formatHours(h) {
    if (typeof fmtHoursHM === 'function') return fmtHoursHM(h);
    h = Number(h) || 0;
    if (h === Math.floor(h)) return h + ' ч';
    return fmtHoursHM(h);
}
/* ---- v1.0.14: «Ч ч. ММ мин.» вместо дробных часов ---- */
function fmtHoursHM(h){h=Number(h)||0;var neg=h<0?'-':'';var tm=Math.round(Math.abs(h)*60);var hh=Math.floor(tm/60),mm=tm-hh*60;if(hh===0&&mm===0)return '0 ч.';if(mm===0)return neg+hh+' ч.';if(hh===0)return neg+mm+' мин.';return neg+hh+' ч. '+mm+' мин.';}
window.fmtHoursHM = fmtHoursHM;
function shortHours(h) {
    h = Number(h) || 0;
    if (h === Math.floor(h)) return String(h);
    return h.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
}
function hoursClass(h) {
    h = Number(h) || 0;
    if (h <= 0) return '';
    if (h < 2) return 'hours-1';
    if (h < 4) return 'hours-2';
    if (h < 6) return 'hours-3';
    return 'hours-4';
}
function heatmapColor(hours) {
    return cellLightGreen(hours) || '';
}

function cellLightGreen(hours) {
    var h = Number(hours) || 0;
    if (h <= 0) return '';
    if (h > 24) h = 24;
    var yellow = [250, 235, 150];
    var green  = [110, 200, 140];
    var pink   = [250, 180, 200];
    var a, b, t;
    if (h <= 8) {
        a = yellow; b = green; t = h / 8;
    } else {
        a = green; b = pink; t = Math.min((h - 8) / 8, 1);
    }
    var r = Math.round(a[0] + (b[0] - a[0]) * t);
    var g = Math.round(a[1] + (b[1] - a[1]) * t);
    var bl = Math.round(a[2] + (b[2] - a[2]) * t);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
}

function initials(name) {
    var parts = String(name || '').trim().split(/\s+/);
    if (!parts.length) return '?';
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + (parts[1][0] || '')).toUpperCase();
}
function statusClass(s) {
    if (s === 'done') return 'status-done';
    if (s === 'in_progress') return 'status-in_progress';
    if (s === 'planned') return 'status-planned';
    if (s === 'blocked') return 'status-blocked';
    return '';
}
function absenceIcon(t) {
    if (t === 'sick_leave') return '🤒';
    if (t === 'business_trip') return '✈️';
    if (t === 'vacation') return '🏖';
    if (t === 'remote') return '🏠';
    return '';
}
function absenceLabel(t) {
    var m = state.absenceTypes || {};
    if (m[t]) return m[t];
    if (t === 'sick_leave') return '🤒 Больничный';
    if (t === 'business_trip') return '✈️ Командировка';
    if (t === 'remote') return '🏠 Удаленка';
    return '🏖 Отпуск';
}
function absenceClass(t) {
    if (t === 'sick_leave') return 'sick_leave';
    if (t === 'business_trip') return 'business_trip';
    if (t === 'remote') return 'remote';
    return 'vacation';
}

/* ============================================================
   ТЕМА
   ============================================================ */
function applyTrkTheme(theme) {
    if (theme !== 'light' && theme !== 'dark') theme = 'dark';
    state.theme = theme;
    document.body.classList.remove('trk-theme-dark', 'trk-theme-light');
    document.body.classList.add('trk-theme-' + theme);
    document.documentElement.setAttribute('data-trk-theme', theme);
    try { localStorage.setItem('reestr_tracker_theme', theme); } catch (e) {}
    var icon = $('trkThemeIcon'), label = $('trkThemeLabel');
    if (icon) icon.textContent = theme === 'dark' ? '☀️' : '🌙';
    if (label) label.textContent = theme === 'dark' ? 'Светлая' : 'Тёмная';
}
(function initTheme() {
    var saved = 'dark';
    try { saved = localStorage.getItem('reestr_tracker_theme') || 'dark'; } catch (e) {}
    applyTrkTheme(saved);
})();
on('trkThemeToggle', 'click', function() {
    applyTrkTheme(state.theme === 'dark' ? 'light' : 'dark');
});

/* ============================================================
   ОПЦИОНАЛЬНЫЙ РАЗВОРОТ ДНЯ
   ============================================================ */
function applyCalExpand(on) {
    state.calExpandOnHover = !!on;
    try { localStorage.setItem('tracker_cal_expand', on ? '1' : '0'); } catch (e) {}
    var grid = $('calGrid');
    if (grid) grid.setAttribute('data-expand', on ? 'on' : 'off');
    document.body.classList.toggle('cal-expand-off', !on);
    var btn = $('calExpandToggle');
    if (btn) btn.classList.toggle('active', on);
    var icon = $('calExpandIcon');
    var label = $('calExpandLabel');
    if (icon) icon.textContent = on ? '⤢' : '⤡';
