/* ============================================================
   PATCH 14 — Вид «Сотрудники» v2: missing + редактирование + многострочность
   ============================================================ */
(function() {
    'use strict';

    function _esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) {
            return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
        });
    }
    function _initials(name) {
        var parts = String(name || '').trim().split(/\s+/);
        if (!parts.length) return '?';
        if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
        return (parts[0][0] + (parts[1][0] || '')).toUpperCase();
    }
    function _fmtH(h) {
        h = Number(h) || 0;
        if (h === Math.floor(h)) return h + ' ч';
        return fmtHoursHM(h);
    }
    function _maskName(name) {
        var st = window.__trkState;
        if (!st || !st.maskNames) return name;
        return String(name == null ? '' : name).split(/\s+/).map(function(w) {
            if (w.length <= 1) return w;
            return w[0] + new Array(w.length).join('*');
        }).join(' ');
    }
    function _isMine(en) {
        var st = window.__trkState;
        var me = (st && st.currentUser) || {};
        if (!me.employee_id) return false;
        return en.employee_id === me.employee_id;
    }
    function _canEdit(en) {
        if (window.REESTR_PERMS && window.REESTR_PERMS['action.log.edit.any']) return true;
        if (window.REESTR_PERMS && window.REESTR_PERMS['action.log.edit.own'] && _isMine(en)) return true;
        return false;
    }
    function _canDelete(en) {
        if (window.REESTR_PERMS && window.REESTR_PERMS['action.log.delete.any']) return true;
        if (window.REESTR_PERMS && window.REESTR_PERMS['action.log.delete.own'] && _isMine(en)) return true;
        return false;
    }

    function _renderMissing(day) {
        var mb = document.getElementById('dayMissingBlock');
        if (!mb) return;
        if (day && day.missing && day.missing.length) {
            mb.style.display = 'block';
            var items = day.missing.map(function(m) {
                return '<span class="dm-item">'
                    + '<span class="dm-dot" style="background:' + _esc(m.color) + '; box-shadow:0 0 6px ' + _esc(m.color) + ';"></span>'
                    + _esc(_maskName(m.name))
                    + (m.department ? ' <span style="opacity:0.7;font-size:0.72rem;">(' + _esc(m.department) + ')</span>' : '')
                    + '</span>';
            }).join('');
            mb.innerHTML = '<div class="dm-title">⚠ Не заполнили день (' + day.missing.length + '):</div>'
                + '<div class="dm-list">' + items + '</div>';
        } else {
            mb.style.display = 'none';
            mb.innerHTML = '';
        }
    }

    window.__trkRenderDayByEmployee = function(entries, totalHours, day) {
        var listEl = document.getElementById('dayList');
        if (!listEl) return false;

        _renderMissing(day);

        if (!entries || !entries.length) {
            listEl.innerHTML = '<div class="day-empty">За этот день отметок нет.</div>';
            return true;
        }

        var byEmp = {};
        entries.forEach(function(en) {
            var eid = en.employee_id || '?';
            if (!byEmp[eid]) {
                byEmp[eid] = {
                    id: eid,
                    name: en.employee_name || '',
                    color: en.employee_color || '#888',
                    dept: en.employee_department || '',
                    tasks: [],
                    total: 0
                };
            }
            byEmp[eid].tasks.push(en);
            byEmp[eid].total += parseFloat(en.hours) || 0;
        });

        var emps = Object.keys(byEmp).map(function(k) { return byEmp[k]; });
        emps.sort(function(a, b) { return b.total - a.total; });

        var html = '<div class="day-emp-tiles">';
        emps.forEach(function(e) {
            var bg = _esc(e.color);
            html += '<div class="day-emp-tile" style="--det-accent:' + bg + ';">'
                + '<div class="det-head">'
                +   '<div class="det-avatar" style="background:' + bg + ';">' + _esc(_initials(e.name)) + '</div>'
                +   '<div class="det-meta">'
                +     '<div class="det-name">' + _esc(_maskName(e.name)) + '</div>'
                +     (e.dept ? '<div class="det-dept">🏢 ' + _esc(e.dept) + '</div>' : '')
                +   '</div>'
                +   '<div class="det-total">' + _fmtH(e.total) + '</div>'
                + '</div>'
                + '<div class="det-tasks">';

            e.tasks.sort(function(a, b) { return (parseFloat(b.hours) || 0) - (parseFloat(a.hours) || 0); });
            e.tasks.forEach(function(en) {
                var ed = _canEdit(en);
                var dl = _canDelete(en);
                html += '<div class="det-task" data-id="' + en.id + '">'
                    + '<span class="det-task-ico">' + _esc(en.task_icon || '📋') + '</span>'
                    + '<div class="det-task-body">'
                    +   '<div class="det-task-name' + (en.overdue ? ' overdue' : '') + '">' + _esc(en.task_name || '') + '</div>'
                    +   (en.comment ? '<div class="det-task-comment">' + _esc(en.comment) + '</div>' : '')
                    + '</div>'
                    + '<span class="det-task-hours">' + _fmtH(en.hours) + '</span>'
                    + '<span class="det-task-actions">'
                    +   (ed ? '<button type="button" class="dict-action-btn" data-act="edit" title="Редактировать">✏️</button>' : '')
                    +   (dl ? '<button type="button" class="dict-action-btn danger" data-act="delete" title="Удалить">🗑</button>' : '')
                    + '</span>'
                    + '</div>';
            });
            html += '</div></div>';
        });
        html += '</div>';
        listEl.innerHTML = html;

        if (typeof window.__trkBindDayEntryActions === 'function') {
            try { window.__trkBindDayEntryActions(listEl, entries); } catch (e) { console.error('[day-view-v2]', e); }
        }
        return true;
    };
})();
/* ============================================================
   PATCH 15 — Дневная карточка: выбор числа колонок I/II
   ============================================================ */
(function() {
    'use strict';

    var KEY = 'tracker_day_cols';

    function getSaved() {
        try {
            var v = parseInt(localStorage.getItem(KEY), 10);
            if (v >= 1 && v <= 4) return v;
        } catch (e) {}
        return 1;
    }

    function syncPicker(cols) {
        var p = document.getElementById('dayColsPicker');
        if (!p) return;
        p.querySelectorAll('button').forEach(function(b) {
            b.classList.toggle('active', parseInt(b.getAttribute('data-cols'), 10) === cols);
        });
    }

    function apply(cols) {
        if (!(cols >= 1 && cols <= 4)) cols = 1;
        var st = window.__trkState;
        if (st) st.dayCols = cols;
        try { localStorage.setItem(KEY, String(cols)); } catch (e) {}
        var list = document.getElementById('dayList');
        if (list) {
            list.setAttribute('data-cols', String(cols));
            list.style.setProperty('--day-cols', String(cols));
        }
        syncPicker(cols);
    }

    document.addEventListener('click', function(e) {
        if (!e.target || !e.target.closest) return;
        var b = e.target.closest('#dayColsPicker button');
        if (!b) return;
        e.preventDefault();
        e.stopPropagation();
        var cols = parseInt(b.getAttribute('data-cols'), 10) || 1;
        apply(cols);
    }, true);

    function hookOpen() {
        if (!window.__trkOpenDayModal || window.__trkOpenDayModal._colPickHooked) return;
        var orig = window.__trkOpenDayModal;
        var wrapped = function() {
            var r = orig.apply(this, arguments);
            setTimeout(function() { apply(getSaved()); }, 40);
            return r;
        };
        wrapped._colPickHooked = true;
        window.__trkOpenDayModal = wrapped;
    }

    function boot() {
        hookOpen();
        setTimeout(hookOpen, 800);
        setTimeout(function() { apply(getSaved()); }, 600);
        var l = document.getElementById('dayList');
        if (l) apply(getSaved());
    }

    if (document.readyState === 'loading') {
