                if (mw.hits === qWords.length) {
                    reason = 'совпадают все слова'; score = 2;
                    hitWords = mw.hitWords;
                } else if (mw.hits >= 2 && mw.hits >= Math.ceil(qWords.length / 2)) {
                    reason = 'совпадают ' + mw.hits + ' из ' + qWords.length + ' слов'; score = 3;
                    hitWords = mw.hitWords;
