// === Расширение payload в fetch ===
(function _wrapFetch(){
    var nativeFetch = window.fetch;
    if (typeof nativeFetch !== 'function' || window.__trkLogFormFocusFetch) return;
    window.__trkLogFormFocusFetch = true;
    window.fetch = function(url, opts){
        if (typeof url !== 'string' || url.indexOf('/api/tracker/log/save') === -1) {
            return nativeFetch.apply(this, arguments);
        }
        if (!opts || (opts.method || 'GET').toUpperCase() !== 'POST') {
            return nativeFetch.apply(this, arguments);
        }
        var _opts = opts;
        try {
            var _body = JSON.parse(opts.body || '{}');
            if (!_body.id) {
                if (!Array.isArray(_body.extra_data) && _extraDraft.length) {
                    _body.extra_data = _extraDraft.map(function(x){ return (x.line || '').trim(); }).filter(Boolean);
                }
                if (!Array.isArray(_body.orders) && _ordersDraft.length) {
                    _body.orders = _ordersDraft
                        .filter(function(x){ return (x.value || '').trim(); })
                        .map(function(x){ return { description: (x.description||'').trim(), value: (x.value||'').trim() }; });
                }
                if (!Array.isArray(_body.links) && _linksDraft.length) {
                    _body.links = _linksDraft
                        .filter(function(x){ return (x.url || '').trim(); })
                        .map(function(x){ return { description: (x.description||'').trim(), url: (x.url||'').trim() }; });
                }
                if (!_body.description && _body.comment) {
                    _body.description = _body.comment;
                }
            }
            _opts = Object.assign({}, opts, { body: JSON.stringify(_body) });
        } catch(e) {}
        var self = this;
        return nativeFetch.call(self, url, _opts).then(function(r){
            if (!r || !r.ok) return r;
            try {
                return r.clone().json().then(function(d){
                    if (d && d.success && d.merge_info && d.merge_info.total_added > 0) {
                        var mi = d.merge_info;
                        var parts = [];
                        if (mi.extra_added) parts.push('доп. данных +' + mi.extra_added);
                        if (mi.orders_added) parts.push('приказов +' + mi.orders_added);
                        if (mi.links_added) parts.push('ссылок +' + mi.links_added);
                        if (mi.added_description) parts.push('описание');
                        if (parts.length && typeof window.__trackerNotify === 'function') {
                            window.__trackerNotify('📎 В задачу добавлено: ' + parts.join(', '));
                        }
                    }
                    return r;
                });
            } catch(e) { return r; }
        });
    };
})();

})();


