            var dtEl = document.getElementById('log_date');
            if (dtEl) dtEl.dispatchEvent(new Event('change', {bubbles:true}));
        }
    } catch(e) { console.error('[log-del-refresh] list', e); }

    // 2. Перерисовать «Назначено, но не заведено»
    try {
        if (typeof window.__trkLogAssignedDecorate === 'function') {
            window.__trkLogAssignedDecorate();
