function _dropFromLocalState(logId){
    if (!logId) return;
    try {
        var st = window.__trkState || {};
        if (st.calendar && st.calendar.days) {
            st.calendar.days.forEach(function(day){
                if (!day.entries) return;
                day.entries = day.entries.filter(function(en){
                    return !(en && (en.id === logId || en.id === String(logId)));
                });
            });
