    window.fetch = function(url, opts){
        var isDel = (typeof url === 'string' && url.indexOf('/api/tracker/log/delete') !== -1);
        if (!isDel) return _native.apply(this, arguments);
        if (!opts || (opts.method || 'GET').toUpperCase() !== 'POST') {
            return _native.apply(this, arguments);
        }
        var logId = null;
        try {
            var b = JSON.parse(opts.body || '{}');
            logId = b.id;
        } catch(e) {}

        var self = this;
        return _native.apply(this, arguments).then(function(r){
            if (!r || !r.ok) return r;
            try {
                return r.clone().json().then(function(d){
                    // PATCH 08 при «Отмена» возвращает {success:false, error:'cancelled'}.
                    // Такие и подобные ошибки не считаем удалением.
