}
function _hideDropdown(){
    if (!_dropdownEl) return;
    _open = false;
    _dropdownEl.setAttribute('hidden', '');
    _dropdownEl.classList.remove('ltd-open');
    _activeIdx = -1;
}
function _refresh(){
    _buildList();
    _renderList();
    if (_open) {
        _positionDropdown();
        _scrollActiveIntoView();
    }
}
function _scrollActiveIntoView(){
    if (!_dropdownEl) return;
    var el = _dropdownEl.querySelector('.ltd-item--active');
    if (el && el.scrollIntoView) {
        try { el.scrollIntoView({ block: 'nearest' }); } catch(e) {}
    }
}

function _moveActive(delta){
    if (!_items.length) return;
    _activeIdx = (_activeIdx + delta + _items.length) % _items.length;
    _renderList();
    _scrollActiveIntoView();
}

function _chooseByIdx(idx){
    if (idx < 0 || idx >= _items.length) return;
    var t = _items[idx];
    if (!t) return;
    var inp = _getInput();
    var hidden = _getHidden();
    if (inp) inp.value = t.name || '';
    if (hidden) hidden.value = t.id || '';
    _hideDropdown();
    if (inp) {
        inp.dispatchEvent(new Event('input', {bubbles:true}));
        inp.dispatchEvent(new Event('change', {bubbles:true}));
    }
}

function _hookInput(){
    var inp = _getInput();
    if (!inp || inp._ltdHooked) return;
    inp._ltdHooked = true;

    inp.addEventListener('focus', function(){
        _refresh();
        _showDropdown();
    });
    inp.addEventListener('click', function(){
        if (!_open) { _refresh(); _showDropdown(); }
        else { _positionDropdown(); }
    });
    inp.addEventListener('input', function(){
        var hidden = _getHidden();
        if (hidden && hidden.value) {
            var st = window.__trkState || {};
            var t = (st.tasks || []).find(function(x){ return x.id === hidden.value; });
            if (!t || (t.name || '') !== inp.value) {
                hidden.value = '';
            }
        }
        _refresh();
        if (!_open) _showDropdown(); else _positionDropdown();
    });
    inp.addEventListener('keydown', function(e){
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            if (!_open) { _refresh(); _showDropdown(); }
            _moveActive(1);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            if (!_open) { _refresh(); _showDropdown(); }
            _moveActive(-1);
        } else if (e.key === 'Enter') {
            if (_open && _activeIdx >= 0 && _items.length) {
                e.preventDefault();
                e.stopPropagation();
                _chooseByIdx(_activeIdx);
            }
        } else if (e.key === 'Escape') {
            if (_open) {
                e.preventDefault();
                e.stopPropagation();
                _hideDropdown();
            }
        }
    });
    inp.addEventListener('blur', function(){
        setTimeout(function(){
            if (!_open) return;
            var drop = _dropdownEl;
            if (drop && drop.matches(':hover')) return;
            _hideDropdown();
        }, 150);
    });
}

