(function _wrapFetch(){
    var nativeFetch = window.fetch;
    if (typeof nativeFetch !== 'function' || window.__trkLogEditTaskMergeFetch) return;
    window.__trkLogEditTaskMergeFetch = true;
    window.fetch = function(url, opts){
        if (typeof url !== 'string' || url.indexOf('/api/tracker/log/save') === -1) {
            return nativeFetch.apply(this, arguments);
        }
        if (!opts || (opts.method || 'GET').toUpperCase() !== 'POST') {
            return nativeFetch.apply(this, arguments);
        }
        var _opts = opts;
        try {
            var _body = JSON.parse(opts.body || '{}');
            // Правка существующей отметки
            if (_body.id) {
                // Подставляем наши multi-поля (всегда, чтобы правки улетели)
                _body.extra_data = (Array.isArray(window.__trkLogExtraDraft)
                    ? window.__trkLogExtraDraft.map(function(x){ return (x.line || '').trim(); }).filter(Boolean)
                    : []);
                _body.orders = (Array.isArray(window.__trkLogOrdersDraft)
                    ? window.__trkLogOrdersDraft.filter(function(x){ return (x.value || '').trim(); })
                        .map(function(x){ return { description: (x.description||'').trim(), value: (x.value||'').trim() }; })
                    : []);
                _body.links = (Array.isArray(window.__trkLogLinksDraft)
                    ? window.__trkLogLinksDraft.filter(function(x){ return (x.url || '').trim(); })
                        .map(function(x){ return { description: (x.description||'').trim(), url: (x.url||'').trim() }; })
                    : []);
                if (!_body.description && _body.comment) _body.description = _body.comment;
                // PATCH v1.1.2: НЕ шлём merge_into_task при правке отметки —
                // бэкенд получал объединённые task+entry списки и сливал
                // их повторно (множественное вложение ссылок/приказов).
            }
            _opts = Object.assign({}, opts, { body: JSON.stringify(_body) });
        } catch(e) {}
        return nativeFetch.call(this, url, _opts);
    };
})();

