    var box = document.getElementById('logLinksList');
    if (!box) return;
    if (!items.length) { box.innerHTML = '<div class="task-links-empty">— нет —</div>'; return; }
    var h = '';
    items.forEach(function(l, i){
        h += '<div class="task-link-row" data-i="' + i + '">'
          +    '<input type="text" class="task-link-desc" value="' + _esc(l.description || '') + '" maxlength="200">'
          +    '<input type="text" class="task-link-url" value="' + _esc(l.url || '') + '" maxlength="1000">'
          +    '<button type="button" class="task-link-del" title="Удалить">×</button>'
          +  '</div>';
    });
    box.innerHTML = h;
    box.querySelectorAll('.task-link-row').forEach(function(row){
        var i = parseInt(row.getAttribute('data-i'), 10);
        var d = row.querySelector('.task-link-desc');
        var u = row.querySelector('.task-link-url');
        if (d) d.addEventListener('input', function(){ if (window.__trkLogLinksDraft && window.__trkLogLinksDraft[i]) window.__trkLogLinksDraft[i].description = this.value; });
        if (u) u.addEventListener('input', function(){ if (window.__trkLogLinksDraft && window.__trkLogLinksDraft[i]) window.__trkLogLinksDraft[i].url = this.value; });
        var xb = row.querySelector('.task-link-del');
        if (xb) xb.addEventListener('click', function(){
            if (Array.isArray(window.__trkLogLinksDraft)) {
                window.__trkLogLinksDraft.splice(i, 1);
                _renderLinks(window.__trkLogLinksDraft);
            }
        });
    });
}

function _populate(logId){
    // PATCH v1.0.20: не перезаписываем, если пользователь уже что-то ввёл.
    if (window.__trkLogModalUserTouched) return;
    var entry = _getEntryFromState(logId);
    var st = window.__trkState || {};
    var taskId = entry ? entry.task_id : '';
    // Если entry нет в state — пробуем вытащить task_id из скрытого #log_task
    if (!taskId) {
        var h = document.getElementById('log_task');
        if (h) taskId = h.value || '';
    }
    var task = taskId ? (st.tasks || []).find(function(x){ return x.id === taskId; }) : null;

    var proceed = function(t){
        var merged = _mergeEntryWithTask(entry || {}, t || {});

        // Описание
        var ta = document.getElementById('log_comment');
        if (ta) ta.value = merged.description || '';

        // Черновики
        if (Array.isArray(window.__trkLogExtraDraft)) {
            window.__trkLogExtraDraft.length = 0;
            (merged.extra_data || []).forEach(function(x){ window.__trkLogExtraDraft.push({ line: x }); });
        }
        if (Array.isArray(window.__trkLogOrdersDraft)) {
            window.__trkLogOrdersDraft.length = 0;
            (merged.orders || []).forEach(function(x){
                window.__trkLogOrdersDraft.push({ description: x.description || '', value: x.value || '' });
            });
        }
        if (Array.isArray(window.__trkLogLinksDraft)) {
            window.__trkLogLinksDraft.length = 0;
            (merged.links || []).forEach(function(x){
                window.__trkLogLinksDraft.push({ description: x.description || '', url: x.url || '' });
            });
        }

        _renderExtra(merged.extra_data || []);
        _renderOrders(merged.orders || []);
        _renderLinks(merged.links || []);

        // Показываем редактируемый блок, скрываем read-only
        var mf = document.getElementById('logMultiFields');
        var mro = document.getElementById('logMultiFieldsRO');
        if (mf) mf.style.display = '';
        if (mro) mro.style.display = 'none';
    };

    if (!task) { proceed(null); return; }
    _fetchTaskIfNeeded(task).then(proceed);
}

