/* ============================================================
   PATCH v1.0.18 — чистый оверлей при удалении отметки
   -------------------------------------------------------------
   - Один оверлей на всю операцию (delete + refresh).
   - Создаётся на самой модалке (.modal), не на .modal-content.
   - Никаких MutationObserver — снимаем ровно в finally.
   - Защита от повторного открытия тем же кликом.
   ============================================================ */
(function(){
'use strict';
if (window.__trkDelLogCleanV1018) return;
window.__trkDelLogCleanV1018 = true;

var OV_ID = 'trkDelLogOverlayV1018';

function _ensureOverlay(modal){
    // modal — это #dayModal или #logModal
    var ov = modal.querySelector('#' + OV_ID);
    if (ov) return ov;
    ov = document.createElement('div');
    ov.id = OV_ID;
    ov.className = 'trk-del-log-overlay';
    ov.innerHTML =
        '<div class="trk-dlo-box">' +
          '<span class="trk-dlo-spinner"></span>' +
          '<span class="trk-dlo-text">Выполняется…</span>' +
        '</div>';
    modal.appendChild(ov);
    return ov;
}

function _setState(modal, state, text){
    var ov = modal.querySelector('#' + OV_ID);
    if (!ov) return;
    ov.classList.remove('trk-dlo-success', 'trk-dlo-error', 'trk-dlo-processing');
    var sp = ov.querySelector('.trk-dlo-spinner');
    var txt = ov.querySelector('.trk-dlo-text');
    if (state === 'success') {
        ov.classList.add('trk-dlo-success');
        if (sp) sp.style.display = 'none';
        var check = ov.querySelector('.trk-dlo-check');
        if (!check) {
            check = document.createElement('span');
            check.className = 'trk-dlo-check';
            check.textContent = '✅';
            if (sp && sp.parentNode) sp.parentNode.insertBefore(check, sp);
        }
        check.style.display = '';
        if (txt) txt.textContent = text || 'Завершено';
    } else if (state === 'error') {
        ov.classList.add('trk-dlo-error');
        if (sp) sp.style.display = 'none';
        var err = ov.querySelector('.trk-dlo-check');
        if (!err) {
            err = document.createElement('span');
            err.className = 'trk-dlo-check';
            err.textContent = '❌';
            if (sp && sp.parentNode) sp.parentNode.insertBefore(err, sp);
        }
        err.style.display = '';
        if (txt) txt.textContent = text || 'Ошибка';
    } else {
        ov.classList.add('trk-dlo-processing');
        if (sp) sp.style.display = '';
        var c = ov.querySelector('.trk-dlo-check');
        if (c) c.style.display = 'none';
        if (txt) txt.textContent = text || 'Выполняется…';
    }
}

function _removeOverlay(modal){
    var ov = modal.querySelector('#' + OV_ID);
    if (ov) ov.remove();
}

// === Хук fetch на /api/tracker/log/delete ===
var _nativeFetch = window.fetch;
if (typeof _nativeFetch === 'function' && !window.__trkDelLogCleanFetch) {
    window.__trkDelLogCleanFetch = true;
    window.fetch = function(url, opts){
        var isDel = (typeof url === 'string' && url.indexOf('/api/tracker/log/delete') !== -1);
        if (!isDel) return _nativeFetch.apply(this, arguments);
        if (!opts || (opts.method || 'GET').toUpperCase() !== 'POST') {
            return _nativeFetch.apply(this, arguments);
        }

        var ctx = window.__trkDelLogCtxV1018;
        var p = _nativeFetch.apply(this, arguments);
        if (!ctx || !ctx.modal) return p;

        var modal = ctx.modal;

        return p.then(function(r){
            if (!r || !r.ok) {
                _setState(modal, 'error', 'Ошибка HTTP ' + (r ? r.status : '?'));
                return Promise.reject(new Error('del_failed'));
            }
            return r.clone().json().then(function(d){
                if (d && d.success === true && !d.cancelled) {
                    _setState(modal, 'success', 'Завершено');
                    // PATCH 1.0.21: возвращаем Response, не plain object.
                    // Раньше `return d` → apiJson получал plain object и падал на r.text().
                    return new Response(JSON.stringify(d), {
                        status: 200,
                        headers: {'Content-Type': 'application/json'}
                    });
                }
                if (d && (d.cancelled || d.error === 'cancelled')) {
                    _setState(modal, 'error', 'Отменено');
                    return Promise.reject(new Error('del_cancelled'));
                }
                _setState(modal, 'error', (d && d.error) || 'Ошибка');
                return Promise.reject(new Error('del_failed'));
            });
        });
    };
}

// === Клик по 🗑 в дневной карточке / блоке «Уже заведено» ===
document.addEventListener('click', function(e){
    if (!e.target || !e.target.closest) return;
    var btn = e.target.closest('.dict-action-btn.danger');
    if (!btn) return;
    var modal = btn.closest('#dayModal') || btn.closest('#logModal');
    if (!modal) return;
    var inDay = btn.closest('#dayList');
    var inExisting = btn.closest('#logDayExistingList');
    if (!inDay && !inExisting) return;
    if (modal.querySelector('#' + OV_ID)) {
        // Уже показываем — повторный клик игнорируем
        e.preventDefault();
        e.stopPropagation();
        if (e.stopImmediatePropagation) e.stopImmediatePropagation();
        return;
    }

    // Ставим контекст для fetch-хука
    window.__trkDelLogCtxV1018 = { modal: modal, ts: Date.now() };
    // Показываем оверлей сразу — до confirm и до запроса
    _ensureOverlay(modal);
    _setState(modal, 'processing', 'Выполняется…');

    // Страховочный таймаут: если что-то пошло не так, снимаем через 120 сек
    var ctx = window.__trkDelLogCtxV1018;
    setTimeout(function(){
        if (window.__trkDelLogCtxV1018 === ctx) {
            _setState(modal, 'error', 'Превышено время ожидания');
            setTimeout(function(){ _removeOverlay(modal); }, 1500);
            window.__trkDelLogCtxV1018 = null;
        }
    }, 120000);
}, true);

// === Обёртка trkRefreshAll: снимаем оверлей после её завершения ===
(function _wrapRefresh(){
    function _apply(){
        if (typeof window.__trkRefreshAll !== 'function') return;
        if (window.__trkRefreshAll._v1018) return;
        var orig = window.__trkRefreshAll;
        var wrapped = function(){
            var p;
            try { p = orig.apply(this, arguments); }
            catch(e) {
                var _ctx = window.__trkDelLogCtxV1018;
                if (_ctx && _ctx.modal) {
                    setTimeout(function(){ _removeOverlay(_ctx.modal); }, 900);
                }
                window.__trkDelLogCtxV1018 = null;
                throw e;
            }
            var restore = function(){
                var _ctx = window.__trkDelLogCtxV1018;
                if (_ctx && _ctx.modal) {
                    // Даём 900 мс показать «✅ Завершено», затем снимаем
                    setTimeout(function(){ _removeOverlay(_ctx.modal); }, 900);
                }
                window.__trkDelLogCtxV1018 = null;
            };
            if (p && typeof p.then === 'function') {
                return p.then(function(v){ restore(); return v; },
                              function(e){ restore(); throw e; });
            }
            restore();
            return p;
        };
        wrapped._v1018 = true;
        window.__trkRefreshAll = wrapped;
    }
    _apply();
    setTimeout(_apply, 500);
    setTimeout(_apply, 1500);
})();

// === Закрытие модалки — аварийное снятие оверлея ===
(function _watchClose(){
    ['dayModal', 'logModal'].forEach(function(id){
        var m = document.getElementById(id);
        if (!m) return;
        new MutationObserver(function(){
            if (!m.classList.contains('active')) {
                _removeOverlay(m);
                var _ctx = window.__trkDelLogCtxV1018;
                if (_ctx && _ctx.modal === m) window.__trkDelLogCtxV1018 = null;
            }
        }).observe(m, { attributes: true, attributeFilter: ['class'] });
    });
})();

window.__trkDelLogClean = {
    show: function(modalId){
        var m = document.getElementById(modalId);
        if (!m) return;
        window.__trkDelLogCtxV1018 = { modal: m, ts: Date.now() };
        _ensureOverlay(m);
        _setState(m, 'processing', 'Выполняется…');
    },
    done: function(modalId){
        var m = document.getElementById(modalId);
        if (!m) return;
