/* ============================================================
   PATCH v1.0.19 — обработка 409 already_logged_today
   -------------------------------------------------------------
   Если сервер вернул, что за этот день у сотрудника уже есть
   отметка по этой задаче — предлагаем пользователю открыть
   её на редактирование вместо создания новой.
   ============================================================ */
(function(){
'use strict';
if (window.__trkLogDupDayV1019) return;
window.__trkLogDupDayV1019 = true;

function _notify(msg, kind){
    if (typeof window.__trackerNotify === 'function') {
        try { window.__trackerNotify(msg, kind); return; } catch(e) {}
    }
}

function _askOpenExisting(info){
    var q = 'У сотрудника «' + (info.employee_name || '') + '» уже есть отметка за '
          + (info.date || '') + '\nпо задаче «' + (info.task_name || '') + '»\n\n'
          + 'Открыть её для редактирования?';
    if (window.confirm(q)) {
        // Пытаемся открыть модалку редактирования
        var st = window.__trkState || {};
        var entry = null;
        if (st.calendar && st.calendar.days) {
            for (var i = 0; i < st.calendar.days.length; i++) {
                var day = st.calendar.days[i];
                if (!day.entries) continue;
                for (var j = 0; j < day.entries.length; j++) {
                    if (String(day.entries[j].id) === String(info.existing_id)) {
                        entry = day.entries[j];
                        break;
                    }
                }
                if (entry) break;
            }
        }
        var lm = document.getElementById('logModal');
        if (lm) lm.classList.remove('active');
        if (entry && typeof window.__trkOpenLogModal === 'function') {
            setTimeout(function(){ window.__trkOpenLogModal(entry); }, 80);
        } else {
            _notify('Не удалось найти отметку в текущем состоянии. Обновите страницу.', 'error');
        }
    } else {
        _notify('Отменено. Открыта новая отметка (не сохранится).', 'error');
    }
}

var _native = window.fetch;
if (typeof _native === 'function' && !window.__trkLogDupDayFetch) {
    window.__trkLogDupDayFetch = true;
    window.fetch = function(url, opts){
        var isSave = (typeof url === 'string' && url.indexOf('/api/tracker/log/save') !== -1);
        var isPost = opts && (opts.method || 'GET').toUpperCase() === 'POST';
        if (!isSave || !isPost) return _native.apply(this, arguments);

        var self = this;
        return _native.apply(this, arguments).then(function(r){
            if (r.status !== 409) return r;
            return r.clone().json().then(function(d){
                if (d && d.error === 'already_logged_today') {
                    setTimeout(function(){ _askOpenExisting(d); }, 60);
                    return new Response(JSON.stringify({success: false, error: 'cancelled'}), {
                        status: 200,
                        headers: {'Content-Type': 'application/json'},
                    });
                }
                return r;
            });
        });
    };
}

window.__trkLogDupDay = { ask: _askOpenExisting };
})();


