        el.style.cssText = 'position:fixed;bottom:16px;left:16px;right:16px;max-height:45vh;overflow:auto;padding:14px 18px;background:rgba(180,30,30,0.97);color:#fff;border-radius:10px;font-family:ui-monospace,Consolas,monospace;font-size:0.78rem;z-index:99999;box-shadow:0 6px 24px rgba(0,0,0,0.55);line-height:1.5;';
