        + '<div style="flex:1;min-width:0;">'
        +   '<div style="font-weight:800;margin-bottom:8px;font-size:0.9rem;">⚠ ' + esc(title) + '</div>'
        +   '<div style="white-space:pre-wrap;word-break:break-word;margin-bottom:6px;">' + esc(body) + '</div>'
