        + '</div>'
        + '<button type="button" onclick="var x=document.getElementById(\'trkErrorBanner\');if(x)x.remove();" style="background:transparent;border:1px solid rgba(255,255,255,0.5);color:#fff;padding:4px 10px;border-radius:6px;cursor:pointer;font-family:inherit;font-size:0.8rem;flex-shrink:0;">Закрыть</button>'
        + '</div>';
}

window.addEventListener('error', function(e){
    if (!e || !e.message) return;
    var stack = (e.error && e.error.stack) ? e.error.stack : ('at ' + (e.filename || '?') + ':' + (e.lineno || '?'));
    _showError('Ошибка в JavaScript', e.message, stack);
});

window.addEventListener('unhandledrejection', function(e){
    var r = e.reason;
    var msg = (r && r.message) ? r.message : String(r);
    if (msg.indexOf('cancelled') !== -1) return;
    var stack = (r && r.stack) ? r.stack : '';
