});

// Защита от не-Response в fetch-цепочке
var _prev = window.fetch;
if (typeof _prev === 'function') {
    window.fetch = function(url, opts){
        return _prev.apply(this, arguments).then(function(r){
            if (r instanceof Response) return r;
            var urlStr = String(url || '');
            var payload;
            try { payload = (typeof r === 'object') ? JSON.stringify(r, null, 2) : String(r); } catch(e) { payload = '[unserializable]'; }
