function _norm(dk) {
    if (!dk) return 8;
    var n = (typeof window.__trkGetDayNorm === 'function') ? window.__trkGetDayNorm(dk) : 8;
    if (typeof n !== 'number' || isNaN(n)) return 8;
    if (n <= 0) return 8;
    return n;
}

// Обёртка над __trkOpenLogModal — норму ставим ДО открытия,
// чтобы updateDayHoursSummary в openLogModal сразу считал правильно,
// а не показывал 0 + 8 = 8.
function _wrap() {
    var _orig = window.__trkOpenLogModal;
    if (typeof _orig !== 'function') return false;
    if (_orig._autoAddHoursV1022) return true;

    var w = function(entry) {
        var _e = entry;
        try {
            if (_e && !_e.id && _e.date) {
                var _h = Number(_e.hours);
                if (isNaN(_h) || _h <= 0 || _h === 8) {
                    _e = Object.assign({}, _e, { hours: _norm(_e.date) });
                }
            }
        } catch (err) {}
        return _orig.call(this, _e);
    };
    w._autoAddHoursV1022 = true;
    window.__trkOpenLogModal = w;
    return true;
}

if (!_wrap()) {
    setTimeout(_wrap, 200);
    setTimeout(_wrap, 800);
    setTimeout(_wrap, 2000);
} else {
    setTimeout(_wrap, 800);
    setTimeout(_wrap, 2000);
}

})();


/* ============================================================
   PATCH 1.0.23 — периодическая проверка обновлений + автоприменение
   ============================================================ */
(function(){
'use strict';
if (window.__trkPeriodicUpdaterV1023) return;
window.__trkPeriodicUpdaterV1023 = true;

var CHECK_INTERVAL_MS = 5 * 60 * 1000;   // раз в 5 минут
var ACTIVITY_GRACE_MS = 60 * 1000;       // если активен <60 сек — отложить
var FIRST_CHECK_DELAY_MS = 2500;         // первая через 2.5 сек после загрузки

window.__trkLastActivity = Date.now();
['mousemove', 'mousedown', 'keydown', 'input', 'scroll', 'touchstart'].forEach(function(ev){
    document.addEventListener(ev, function(){ window.__trkLastActivity = Date.now(); }, true);
});

function _hasUpdatePerms(){
    var p = window.REESTR_PERMS || {};
    return !!(p['tab.updater'] || p['action.updater.apply']);
}
function _isDismissed(){ try { return sessionStorage.getItem('trk_update_dismissed_periodic') === '1'; } catch(e){ return false; } }
function _setDismissed(v){ try { sessionStorage.setItem('trk_update_dismissed_periodic', v ? '1' : '0'); } catch(e){} }

function _esc(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
}

function _safeJson(url, opts){
    return fetch(url, opts || {credentials: 'same-origin'})
        .then(function(r){
            var ct = r.headers.get('content-type') || '';
            if (ct.indexOf('application/json') !== -1) return r.json();
            return null;
        })
        .catch(function(){ return null; });
}

function _anyModalOpen(){
    return document.querySelectorAll('.modal.active').length > 0;
}

function _userActiveRecently(){
    return (Date.now() - (window.__trkLastActivity || 0)) < ACTIVITY_GRACE_MS;
}

function _getModal(){
    var m = document.getElementById('trkPeriodicUpdateModal');
    if (m) return m;
    m = document.createElement('div');
