    m.className = 'modal';
    m.style.setProperty('z-index', '9200', 'important');
    m.innerHTML = ''
        + '<div class="modal-content" style="max-width:560px;">'
        + '  <h2 style="color:#f5d76e;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid rgba(245,215,110,0.20);">⬆ Доступно обновление</h2>'
        + '  <div id="trkPUBody" style="font-size:0.9rem;line-height:1.5;max-height:50vh;overflow:auto;"></div>'
        + '  <div style="margin-top:14px;padding:10px 12px;background:var(--trk-hover-row);border-radius:8px;display:flex;align-items:center;gap:8px;">'
        + '    <input type="checkbox" id="trkPUAutoCb" style="width:16px;height:16px;accent-color:var(--trk-accent);cursor:pointer;">'
        + '    <label for="trkPUAutoCb" style="font-size:0.85rem;color:var(--trk-text);cursor:pointer;margin:0;">Устанавливать автоматически без подтверждения</label>'
        + '  </div>'
        + '  <div class="modal-actions" style="margin-top:16px;">'
        + '    <button type="button" class="btn btn-secondary" id="trkPUCancel">Не сейчас</button>'
