function _runUpdate(){
    if (window.__trkUpdateRunning) return;
    window.__trkUpdateRunning = true;

    var loader = document.getElementById('globalLoader');
    if (loader) {
        loader.classList.add('active');
        var t = loader.querySelector('.gl-text');
        if (t) t.textContent = 'Проверка обновления...';
    }

    var csrf = window.REESTR_CSRF || '';
    var hdrs = {'Content-Type': 'application/json'};
    if (csrf) hdrs['X-CSRF-Token'] = csrf;

    _safeJson('/api/plugins/updater/check', {
        method: 'POST', credentials: 'same-origin', headers: hdrs
    })
    .then(function(d){
        if (!d || !d.success || !d.dry_run || !d.dry_run.rc_ok) {
            throw new Error('Проверка не пройдена: ' + ((d && d.error) || 'неизвестно'));
        }
        if (!d.pending || !d.pending.length) {
            throw new Error('Нет патчей к применению');
        }
        if (loader) {
            var t = loader.querySelector('.gl-text');
            if (t) t.textContent = 'Применение патчей...';
        }
        return _safeJson('/api/plugins/updater/apply', {
            method: 'POST', credentials: 'same-origin', headers: hdrs
        });
    })
    .then(function(d){
        if (!d || !d.success) {
            throw new Error('Ошибка применения: ' + ((d && d.error) || 'неизвестно'));
        }
        if (loader) {
            var t = loader.querySelector('.gl-text');
            if (t) t.textContent = 'Перезапуск сервера...';
        }
        return _safeJson('/api/settings/restart', {
            method: 'POST', credentials: 'same-origin', headers: hdrs
        });
    })
    .then(function(d){
        if (!d || !d.success) {
            throw new Error('Ошибка перезапуска: ' + ((d && d.error) || 'неизвестно'));
        }
        var attempts = 0;
        var iv = setInterval(function(){
            attempts++;
            // PATCH 1.0.23: GET вместо HEAD — надёжнее за reverse-proxy
            fetch('/login', {method: 'GET', cache: 'no-store', credentials: 'same-origin'})
                .then(function(r){
                    if (r && (r.status === 200 || r.status === 302 || r.ok)) {
                        clearInterval(iv);
                        location.reload();
                    }
                })
                .catch(function(){
                    if (attempts > 30) {
                        clearInterval(iv);
                        window.__trkUpdateRunning = false;
                        if (loader) loader.classList.remove('active');
                        alert('Сервер не поднялся за 30 сек. Запустите START.bat вручную.');
                    }
                });
        }, 1000);
    })
    .catch(function(err){
        window.__trkUpdateRunning = false;
        if (loader) loader.classList.remove('active');
        var msg = (err && err.message) || 'неизвестная ошибка';
        if (typeof window.__trackerNotify === 'function') {
            window.__trackerNotify('❌ ' + msg, 'error');
        } else {
            console.warn('[updater] ' + msg);
        }
    });
}

function _check(){
    if (!_hasUpdatePerms()) return;
    if (window.__trkUpdateRunning) return;
    if (_anyModalOpen()) return;
    if (_userActiveRecently()) return;

    Promise.all([
        _safeJson('/api/plugins/updater/status'),
        _safeJson('/api/plugins/updater/settings')
    ]).then(function(results){
        var st = results[0];
        var settings = results[1];
        if (!st || !st.success) return;
        if (!st.pending || !st.pending.length) return;

        var isAuto = settings && settings.success && settings.auto_update;
        if (isAuto) {
            _runUpdate();
        } else if (!_isDismissed()) {
            _showModal(st);
        }
    }).catch(function(){});
}

setTimeout(_check, FIRST_CHECK_DELAY_MS);
setInterval(_check, CHECK_INTERVAL_MS);

window.__trkPeriodicUpdateCheck = _check;
window.__trkPeriodicUpdateRun = _runUpdate;

})();


