        if (!list) return null;
        var tl = document.getElementById('tasksTimelineList');
        if (!tl) {
            tl = document.createElement('div');
            tl.id = 'tasksTimelineList';
            tl.className = 'tasks-timeline';
            tl.style.display = 'none';
