# ============================================================
# Утилиты
# ============================================================
def _parse_iso(s):
    try:
        return datetime.strptime(s, '%Y-%m-%d').date()
    except Exception:
        return None


def _period_from_args():
    preset = (request.args.get('preset') or 'month').strip().lower()
    today = date.today()
    if preset == 'week':
        monday = today - timedelta(days=today.weekday())
        return monday, today, 'week'
    if preset == 'month':
        return today.replace(day=1), today, 'month'
    if preset == 'quarter':
        m = (today.month - 1) // 3 * 3 + 1
        return today.replace(month=m, day=1), today, 'quarter'
    if preset == 'year':
        return today.replace(month=1, day=1), today, 'year'
    d1 = _parse_iso(request.args.get('from') or '')
    d2 = _parse_iso(request.args.get('to') or '')
    if d1 and d2 and d1 <= d2:
        return d1, d2, 'custom'
    return today.replace(day=1), today, 'month'


def _workdays_between(d1, d2):
    n = 0
    cur = d1
    while cur <= d2:
        if cur.weekday() < 5:
            n += 1
        cur += timedelta(days=1)
    return n


# ============================================================
# Регистрация
# ============================================================
def register(app, db, hooks):
    print('[pulse] v' + __version__ + ' · ' + __description__)

    @app.route('/plugins-assets/pulse.js', methods=['GET'])
    def _pl_js():
        return app.response_class(_JS, mimetype='application/javascript')

    @app.route('/plugins/pulse/', methods=['GET'])
    def _pl_page():
        try:
            from auth import current_user, user_has
            u = current_user(db)
            if not u:
                return redirect('/login')
            if not user_has(db, u, 'plugin.pulse.use'):
                return redirect('/')
        except Exception:
            return redirect('/login')
        return Response(_page_html(), mimetype='text/html')

    @app.route('/api/plugins/pulse/data', methods=['GET'])
    def _pl_data():
        try:
            from auth import current_user, user_has
            u = current_user(db)
            if not u:
                return jsonify({'success': False, 'error': 'auth'}), 401
            if not user_has(db, u, 'plugin.pulse.use'):
                return jsonify({'success': False, 'error': 'forbidden'}), 403
        except Exception:
            return jsonify({'success': False, 'error': 'auth'}), 401

        d1, d2, preset = _period_from_args()
        d1_iso = d1.strftime('%Y-%m-%d')
        d2_iso = d2.strftime('%Y-%m-%d')
        wd = _workdays_between(d1, d2)

        data = db.load_all()
        today = date.today()
        today_iso = today.strftime('%Y-%m-%d')
        soon_iso = (today + timedelta(days=3)).strftime('%Y-%m-%d')

        teams_by_id = {t['id']: t for t in data.get('teams', [])}
        depts_by_id = {d['id']: d for d in data.get('departments', [])}
        emps_by_id = {e['id']: e for e in data.get('employees', [])}

        # Данные по логам
        last_log = {}
        logs_by_task = {}
        hours_period = 0.0
        done_ids_period = set()
        activity_map = {}

        try:
            _ifu = str(db.get_setting('stats_ignore_future', '1')) != '0'
        except Exception:
            _ifu = True
        for l in data.get('log', []):
            tid = l.get('task_id')
            if not tid:
                continue
            ld = l.get('date') or ''
            if _ifu and ld > today_iso:
                continue
            eid = l.get('employee_id') or ''

            logs_by_task.setdefault(tid, []).append(l)
            if not last_log.get(tid) or ld > last_log[tid]:
                last_log[tid] = ld

            try:
                h = float(l.get('hours') or 0)
            except Exception:
                h = 0

            if d1_iso <= ld <= d2_iso:
                hours_period += h
                if l.get('status') == 'done':
                    done_ids_period.add(tid)
                row = activity_map.setdefault(ld, {'hours': 0.0, 'done': 0})
                row['hours'] += h
                if l.get('status') == 'done':
                    row['done'] += 1

        # Задачи
        statuses = {'active': 0, 'paused': 0, 'overdue': 0, 'done': 0, 'archived': 0}
        overdue, stale, deadline_soon, orphan, no_assignees, long_running = [], [], [], [], [], []
        by_dept = {}
        by_team = {}
        overdue_days_counter = {}
        overdue_emps = {}
        stale_emps = {}

        for t in data.get('tasks', []):
            st = t.get('status', 'active')
            tid = t['id']
            assigns = [a for a in (t.get('assignees') or []) if a]
            dl = t.get('deadline') or ''

            if st == 'active':
                statuses['active'] += 1
            elif st == 'paused':
                statuses['paused'] += 1
            elif st == 'done':
                statuses['done'] += 1
            elif st == 'archived':
                statuses['archived'] += 1

            if st in ('active', 'paused'):
                # просрочка
                if dl and dl < today_iso:
                    statuses['overdue'] += 1
                    try:
                        days_past = (today - datetime.strptime(dl, '%Y-%m-%d').date()).days
                    except Exception:
                        days_past = 0
                    overdue.append({
                        'icon': t.get('icon', '📋'),
                        'name': t.get('name', ''),
                        'meta': 'дедлайн ' + dl,
                        'pill': str(days_past) + ' дн',
                    })
                    key = dl
                    rec = overdue_days_counter.setdefault(key, {'count': 0, 'days_past': days_past})
                    rec['count'] += 1
                    rec['days_past'] = max(rec['days_past'], days_past)
                    for a in assigns:
                        e = emps_by_id.get(a)
                        if not e:
                            continue
                        r = overdue_emps.setdefault(a, {'overdue': 0, 'max_days': 0, 'name': e.get('name', a), 'color': e.get('color', '#888')})
                        r['overdue'] += 1
                        r['max_days'] = max(r['max_days'], days_past)

                # нет активности
                ll = last_log.get(tid)
                if ll:
                    try:
                        since = (today - datetime.strptime(ll, '%Y-%m-%d').date()).days
                    except Exception:
                        since = 0
                    if since >= 7:
                        stale.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': 'последняя ' + ll, 'pill': str(since) + ' дн'})
                        for a in assigns:
                            e = emps_by_id.get(a)
                            if not e:
                                continue
                            r = stale_emps.setdefault(a, {'count': 0, 'max_days': 0, 'name': e.get('name', a), 'color': e.get('color', '#888')})
                            r['count'] += 1
                            r['max_days'] = max(r['max_days'], since)
                else:
                    sd = t.get('start_date') or ''
                    if sd:
                        try:
                            since = (today - datetime.strptime(sd, '%Y-%m-%d').date()).days
                        except Exception:
                            since = 0
                        if since >= 7:
                            stale.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': 'старт ' + sd, 'pill': str(since) + ' дн'})

                # дедлайн близко
                if dl and today_iso <= dl <= soon_iso:
                    if not logs_by_task.get(tid):
                        deadline_soon.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': 'дедлайн ' + dl, 'pill': ''})

                # уволенные
                if assigns:
                    fired = [a for a in assigns if emps_by_id.get(a, {}).get('fired')]
                    if fired and len(fired) == len(assigns):
                        orphan.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': '', 'pill': 'все уволены'})
                else:
                    no_assignees.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': '', 'pill': 'никого'})

                # долго в работе
                sd = t.get('start_date') or ''
                if sd:
                    try:
                        days_in_work = (today - datetime.strptime(sd, '%Y-%m-%d').date()).days
                    except Exception:
                        days_in_work = 0
                    if days_in_work >= 30:
                        long_running.append({'icon': t.get('icon', '📋'), 'name': t.get('name', ''), 'meta': 'старт ' + sd, 'pill': str(days_in_work) + ' дн'})

                # Сводка по отделам — часы за период
                dept_keys = set()
                if t.get('department_ids'):
                    for d in t['department_ids']:
                        dept_keys.add(d)
                else:
                    for a in assigns:
                        e = emps_by_id.get(a)
                        if e and e.get('department_id'):
                            dept_keys.add(e['department_id'])
                for dk in dept_keys:
                    dname = (depts_by_id.get(dk) or {}).get('name', dk)
                    r = by_dept.setdefault(dk, {'name': dname, 'tasks': 0, 'overdue': 0, 'hours': 0.0})
                    r['tasks'] += 1
                    if dl and dl < today_iso:
                        r['overdue'] += 1
                    for l in logs_by_task.get(tid, []):
                        ld = l.get('date') or ''
                        if d1_iso <= ld <= d2_iso:
                            try:
                                r['hours'] += float(l.get('hours') or 0)
                            except Exception:
                                pass

                # Сводка по командам — часы за период
                team_keys = set()
                for tm in data.get('teams', []):
                    tm_members = set(tm.get('member_ids') or [])
                    if tm.get('manager_id'):
                        tm_members.add(tm['manager_id'])
                    if set(assigns) & tm_members:
                        team_keys.add(tm['id'])
                for tk in team_keys:
                    tm = teams_by_id.get(tk) or {}
                    r = by_team.setdefault(tk, {'name': tm.get('name', tk), 'tasks': 0, 'overdue': 0, 'hours': 0.0})
                    r['tasks'] += 1
                    if dl and dl < today_iso:
                        r['overdue'] += 1
                    for l in logs_by_task.get(tid, []):
                        ld = l.get('date') or ''
                        if d1_iso <= ld <= d2_iso:
                            try:
                                r['hours'] += float(l.get('hours') or 0)
                            except Exception:
                                pass

        for k in by_dept.values():
            k['hours'] = round(k['hours'] * 4) / 4
        for k in by_team.values():
            k['hours'] = round(k['hours'] * 4) / 4

        overdue_emps_list = sorted([dict(v) for v in overdue_emps.values()], key=lambda x: (-x['overdue'], -x['max_days']))[:10]
        stale_emps_list = sorted([dict(v) for v in stale_emps.values()], key=lambda x: (-x['count'], -x['max_days']))[:10]

        # Динамика за выбранный период — все дни
        activity = []
        span = (d2 - d1).days
        max_days = 90  # ограничим отображение — если период длиннее, схлопнем по неделям
        if span <= max_days:
            cur = d1
            while cur <= d2:
                dk = cur.strftime('%Y-%m-%d')
                row = activity_map.get(dk, {'hours': 0.0, 'done': 0})
                activity.append({'date': dk, 'hours': round(row['hours'] * 4) / 4, 'done': row['done']})
                cur += timedelta(days=1)
        else:
            # агрегируем по неделям
            cur = d1
            while cur <= d2:
                week_end = min(cur + timedelta(days=6), d2)
                wh = 0.0
                wd_cnt = 0
                c2 = cur
                while c2 <= week_end:
                    dk = c2.strftime('%Y-%m-%d')
                    row = activity_map.get(dk)
                    if row:
                        wh += row['hours']
                        wd_cnt += row['done']
                    c2 += timedelta(days=1)
                activity.append({'date': cur.strftime('%Y-%m-%d'), 'hours': round(wh * 4) / 4, 'done': wd_cnt})
                cur += timedelta(days=7)

        overdue_days = [{'deadline': k, 'count': v['count'], 'days_past': v['days_past']} for k, v in overdue_days_counter.items()]
        overdue_days.sort(key=lambda x: -x['count'])

        # Health score
        # PATCH v1.0.37: overdue — подмножество active+paused (deadline < today
        # при status in active/paused), поэтому total_active считал просроченные
        # дважды и завышал health в 1.5 раза. Правильно — только active+paused.
        total_active = statuses['active'] + statuses['paused']
        if total_active > 0:
            ov_rate = statuses['overdue'] / total_active
            stale_rate = len(stale) / total_active
            noasg_rate = len(no_assignees) / total_active
            orphan_rate = len(orphan) / total_active
            # Веса: 50 + 20 + 15 + 15 = 100 — максимум штрафа при 100% каждой проблемы
            penalty = ov_rate * 50 + stale_rate * 20 + noasg_rate * 15 + orphan_rate * 15
            # PATCH v1.0.5: было `100 - penalty * 100` — health всегда 0 при penalty>1
            health = max(0, min(100, round(100 - penalty)))
        else:
            health = 100

        return jsonify({
            'success': True,
            'from': d1_iso,
            'to': d2_iso,
            'preset': preset,
            'workdays': wd,
            'stats': {
                'tasks_total': total_active,
                'tasks_overdue': statuses['overdue'],
                'tasks_soon': len(deadline_soon),
                'tasks_stale': len(stale),
                'tasks_no_assignees': len(no_assignees),
                'tasks_orphan': len(orphan),
                'hours_period': round(hours_period * 4) / 4,
                'done_period': len(done_ids_period),
                'health_score': health,
            },
            'statuses': statuses,
            'activity': activity,
            'overdue_days': overdue_days,
            'by_dept': sorted(by_dept.values(), key=lambda x: -x['overdue']),
            'by_team': sorted(by_team.values(), key=lambda x: -x['overdue']),
            'overdue_emps': overdue_emps_list,
            'stale_emps': stale_emps_list,
            'overdue': overdue[:30],
            'stale': stale[:30],
            'deadline_soon': deadline_soon[:30],
            'orphan': orphan[:30],
            'no_assignees': no_assignees[:30],
            'long_running': long_running[:30],
        })

    def on_startup(**ctx):
        print('[pulse] готов — с выбором периода')

    hooks.on('on_startup', on_startup)

"""plugins/stats_teams.py — Статистика: Отделы (верхний уровень) + Команды (как раньше)."""

__version__ = '4.0'
__description__ = 'Статистика: KPI отделов + команд, radar, лидерборд, тренды, топ-сотрудники'

from datetime import date, datetime, timedelta
from flask import request, jsonify, Response, redirect


# ============================================================
# Утилиты
# ============================================================
def _parse_iso(s):
    try:
        return datetime.strptime(s, '%Y-%m-%d').date()
    except Exception:
        return None


def _iso(d):
    return d.strftime('%Y-%m-%d')


def _period_from_args():
    preset = (request.args.get('preset') or 'month').strip().lower()
    today = date.today()
    if preset == 'week':
        monday = today - timedelta(days=today.weekday())
        return monday, today, 'week'
    if preset == 'month':
        return today.replace(day=1), today, 'month'
    if preset == 'prev_month':
        first_cur = today.replace(day=1)
        last_prev = first_cur - timedelta(days=1)
        return last_prev.replace(day=1), last_prev, 'prev_month'
    if preset == 'quarter':
        m = (today.month - 1) // 3 * 3 + 1
        return today.replace(month=m, day=1), today, 'quarter'
    d1 = _parse_iso(request.args.get('from') or '')
    d2 = _parse_iso(request.args.get('to') or '')
    if d1 and d2 and d1 <= d2:
        return d1, d2, 'custom'
    return today.replace(day=1), today, 'month'


def _prev_period(d1, d2):
    span = (d2 - d1).days + 1
    return d1 - timedelta(days=span), d1 - timedelta(days=1)


def _workdays_between(d1, d2):
    n = 0
    cur = d1
    while cur <= d2:
        if cur.weekday() < 5:
            n += 1
        cur += timedelta(days=1)
    return n


def _emp_stats(data, emp_ids, d1, d2, ignore_future=True):
    today = _iso(date.today())
    logs = data.get('log', [])
    all_assignees = {}
    for t in data.get('tasks', []):
        for a in (t.get('assignees') or []):
            all_assignees.setdefault(a, []).append(t)

    # PATCH v1.0.5: предвычисляем last_done по (employee, task) за один проход.
    # Раньше был O(E*T*N) — теперь O(N + E*T).
    last_done_map = {}
    for l in logs:
        if l.get('status') != 'done':
            continue
        eid = l.get('employee_id')
        tid = l.get('task_id')
        d = l.get('date') or ''
        if not eid or not tid or not d:
            continue
        key = (eid, tid)
        cur = last_done_map.get(key)
        if not cur or d > cur:
            last_done_map[key] = d

    per = {}
    for eid in emp_ids:
        per[eid] = {'hours': 0.0, 'tasks_done': 0, 'logs_count': 0,
                    'active_days': set(), 'overdue_tasks': [], 'done_task_ids': set()}

    for l in logs:
        ld = l.get('date') or ''
        if ld < _iso(d1) or ld > _iso(d2):
            continue
        if ignore_future and ld > today:
            continue
        eid = l.get('employee_id')
        if eid not in per:
            continue
        per[eid]['logs_count'] += 1
        try:
            h = float(l.get('hours') or 0)
        except Exception:
            h = 0
        per[eid]['hours'] += h
        per[eid]['active_days'].add(ld)
        tid = l.get('task_id')
        if tid and l.get('status') == 'done':
            per[eid]['done_task_ids'].add(tid)

    for eid, st in per.items():
        st['hours'] = round(st['hours'] * 4) / 4
        st['tasks_done'] = len(st['done_task_ids'])
        st['active_days'] = len(st['active_days'])
        overdue = []
        for t in all_assignees.get(eid, []):
            if t.get('status') not in ('active', 'paused'):
                continue
            dl = t.get('deadline') or ''
            if not dl or dl >= today:
                continue
            if last_done_map.get((eid, t['id'])):
                continue
            overdue.append(t)
        st['overdue_tasks'] = overdue
        st['overdue_count'] = len(overdue)

    return per


def _compute_extras(data, emp_ids, d1, d2, ignore_future=True):
    from datetime import datetime as _dt
    tasks = {t['id']: t for t in data.get('tasks', [])}
    logs = data.get('log', [])
    start_iso = _iso(d1)
    end_iso = _iso(d2)

    on_time = 0
    late = 0
    cycles = []

    for l in logs:
        if l.get('employee_id') not in emp_ids:
            continue
        if l.get('status') != 'done':
            continue
        ld = l.get('date') or ''
        if ld < start_iso or ld > end_iso:
            continue
        if ignore_future and ld > _iso(date.today()):
            continue
        t = tasks.get(l.get('task_id'))
        if not t:
            continue
        dl = t.get('deadline') or ''
        if dl:
            if ld <= dl:
                on_time += 1
            else:
                late += 1
        fdate = None
        for l2 in logs:
            if l2.get('task_id') != l.get('task_id'):
                continue
            if l2.get('employee_id') not in emp_ids:
                continue
            d = l2.get('date') or ''
            if not fdate or d < fdate:
                fdate = d
        if fdate and ld >= fdate:
            try:
                delta = (_dt.strptime(ld, '%Y-%m-%d') - _dt.strptime(fdate, '%Y-%m-%d')).days
                cycles.append(delta)
            except Exception:
                pass

    total_done = on_time + late
    on_time_pct = round(100 * on_time / total_done) if total_done else 0
    cycle_avg = round(sum(cycles) / len(cycles), 1) if cycles else 0

    trend = []
    end = d2
    for w in range(4):
        w_end = end - timedelta(days=7 * w)
        w_start = w_end - timedelta(days=6)
        if w_start < d1 - timedelta(days=90):
            break
        hours = 0.0
        for l in logs:
            if l.get('employee_id') not in emp_ids:
                continue
            ld = l.get('date') or ''
            if _iso(w_start) <= ld <= _iso(w_end):
                try:
                    hours += float(l.get('hours') or 0)
                except Exception:
                    pass
        trend.append({'from': _iso(w_start), 'to': _iso(w_end), 'hours': round(hours * 4) / 4})
    trend.reverse()

    return {'on_time_pct': on_time_pct, 'cycle_avg_days': cycle_avg, 'trend': trend}


def _aggregate(data, name, emp_ids, d1, d2, prev=None, extra=None, ignore_future=True):
    """Универсальный агрегатор для команды и отдела."""
    per = _emp_stats(data, emp_ids, d1, d2, ignore_future=ignore_future)
    wd = _workdays_between(d1, d2)
    total_hours = 0.0
    total_done = 0
    total_overdue = 0
    active = 0
    for st in per.values():
        total_hours += st['hours']
        total_done += st['tasks_done']
        total_overdue += st['overdue_count']
        if st['hours'] > 0:
            active += 1
    total_hours = round(total_hours * 4) / 4
    possible_hours = wd * 8 * len(emp_ids)
    coverage = round(100 * total_hours / possible_hours) if possible_hours else 0
    avg_per_emp = round(total_hours / len(emp_ids) * 4) / 4 if emp_ids else 0

    def meta(eid):
        e = next((x for x in data.get('employees', []) if x['id'] == eid), None)
        return {'id': eid, 'name': (e.get('name') if e else eid), 'color': (e.get('color') if e else '#888')}

    ranking_hours = sorted([dict(meta(eid), hours=st['hours']) for eid, st in per.items()], key=lambda x: -x['hours'])[:3]
    ranking_done = sorted([dict(meta(eid), tasks_done=st['tasks_done']) for eid, st in per.items() if st['tasks_done'] > 0], key=lambda x: -x['tasks_done'])[:3]
    ranking_coverage = sorted([dict(meta(eid), coverage=round(100 * st['active_days'] / wd) if wd else 0) for eid, st in per.items()], key=lambda x: -x['coverage'])[:3]

    extras = _compute_extras(data, emp_ids, d1, d2, ignore_future=ignore_future)

    def _delta(cur, prv):
        try:
            cur = float(cur); prv = float(prv)
            if prv == 0:
                return {'abs': round(cur, 2), 'pct': 0 if cur == 0 else 100}
            return {'abs': round(cur - prv, 2), 'pct': round(100 * (cur - prv) / prv)}
        except Exception:
            return {'abs': 0, 'pct': 0}

    deltas = {}
    if prev:
        deltas = {
            'hours': _delta(total_hours, prev.get('total_hours', 0)),
            'done': _delta(total_done, prev.get('total_done', 0)),
            'coverage': _delta(coverage, prev.get('coverage', 0)),
            'overdue': _delta(total_overdue, prev.get('total_overdue', 0)),
        }

    result = {
        'name': name,
        'members_count': len(emp_ids),
        'active_members': active,
        'total_hours': total_hours,
        'total_done': total_done,
        'total_overdue': total_overdue,
        'coverage': coverage,
        'possible_hours': possible_hours,
        'avg_per_emp': avg_per_emp,
        'workdays': wd,
        'top_hours': ranking_hours,
        'top_done': ranking_done,
        'top_coverage': ranking_coverage,
        'extras': extras,
        'deltas': deltas,
        'overdue_tasks': [{'id': t['id'], 'name': t.get('name', ''), 'icon': t.get('icon', '📋'), 'deadline': t.get('deadline', '')} for t in sum([st['overdue_tasks'] for st in per.values()], [])][:10],
    }
    if extra:
        result.update(extra)
    return result


