      var el=document.getElementById('reportsList');
      if(!d.success||!d.items||!d.items.length){el.innerHTML='<div class="empty">Отчётов пока нет — нажмите «Сохранить отчёт»</div>';return;}
      el.innerHTML=d.items.map(function(it){
