def _collect_stats(db):
    data = db.load_all()
    today = date.today()
    monday = _monday_of(today)
    sunday = monday + timedelta(days=6)
    from_iso = monday.strftime('%Y-%m-%d')
    to_iso = sunday.strftime('%Y-%m-%d')

    employees = {e['id']: e for e in data.get('employees', [])}
    holidays = data.get('holidays', {}) or {}

    logs = data.get('log', [])
    week_logs = [l for l in logs if from_iso <= (l.get('date') or '') <= to_iso]

    hours_by_emp = {}
    hours_total = 0.0
    for l in week_logs:
        try:
            h = float(l.get('hours') or 0)
        except Exception:
            h = 0
        eid = l.get('employee_id')
        hours_by_emp[eid] = hours_by_emp.get(eid, 0.0) + h
        hours_total += h

    top_employees = []
    for eid, h in sorted(hours_by_emp.items(), key=lambda x: -x[1])[:5]:
        e = employees.get(eid)
        if not e:
            continue
        top_employees.append({
            'name': e.get('name', ''),
            'color': e.get('color', '#888'),
            'hours': round(h * 4) / 4,
        })

    tasks = data.get('tasks', [])
    overdue_count = 0
    for t in tasks:
        if t.get('status') not in ('active', 'paused'):
            continue
        dl = t.get('deadline') or ''
        if dl and dl < today.strftime('%Y-%m-%d'):
            overdue_count += 1

    workdays = 0
    cur = monday
    while cur <= sunday:
        if cur.weekday() < 5 and cur.strftime('%Y-%m-%d') not in holidays:
            workdays += 1
        cur += timedelta(days=1)

    # PATCH 1.0.17: норма по режиму графика
    try:
        _sched_ws = db.get_setting('work_schedule_mode', 'legacy')
    except Exception:
        _sched_ws = 'legacy'
    _norm_per_day_ws = 0.0
    _cur_ws = monday
    while _cur_ws <= sunday:
        _iso_ws = _cur_ws.strftime('%Y-%m-%d')
        _wd_ws = _cur_ws.weekday()
        if _wd_ws < 5 and _iso_ws not in holidays:
            if _sched_ws == 'extended':
                _norm_per_day_ws += 7.75 if _wd_ws == 4 else 8.25
            else:
                _norm_per_day_ws += 8.0
        _cur_ws += timedelta(days=1)
    norm_total = _norm_per_day_ws * max(1, len(hours_by_emp))
    avg_load = 0
    if norm_total > 0:
        avg_load = round((hours_total / norm_total) * 100)

    return {
        'from': from_iso,
        'to': to_iso,
        'from_fmt': monday.strftime('%d.%m'),
        'to_fmt': sunday.strftime('%d.%m'),
        'hours_total': round(hours_total * 4) / 4,
        'top_employees': top_employees,
        'overdue_count': overdue_count,
        'working_days': workdays,
        'avg_load': avg_load,
    }


