                ttHtml = '<div class="tt-title">' + esc(r.name) + '</div><div style="color:var(--pg-meta);font-size:.7rem;margin-bottom:4px;">' + c.date + '</div>';
                if (c.hours > 0) ttHtml += '<div class="tt-row"><span>Часов:</span><b>' + fmtHoursHM(c.hours) + '</b></div>';
