            }
            var ttId = 'tt_' + r.id + '_' + idx;
            if (ttHtml) _TT_DATA[ttId] = ttHtml;
            html += '<td class="day-cell"><div class="' + pillCls + '" data-tt="' + ttId + '">' + content + '</div></td>';
        });
        html += '</tr>';
    });
    html += '</tbody></table>';
    wrap.innerHTML = html;

    var ttEl = document.getElementById('hmTooltip');
